INSERT INTO "user" ("id", "handle", "name", "is_adult_confirmed", "onboarded_at", "kid_ages")
INSERT INTO "battle" ("id", "slug", "author_id", "title", "context", "category_id", "tags", "deadline", "created_at") VALUES
  ('ask_m_groceries', 'tubEfbLu', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Groceries are eating my whole paycheck. Cut takeout completely or just cut back?', NULL, 'other', '{"askingPreset":"m_groceries"}'::jsonb, now() + interval '365 days', now() - interval '24 hours'),
  ('ask_m_debt_tell', 'ery8TCBC', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Do I tell my partner about my $8k credit card debt before we move in together?', NULL, 'other', '{"askingPreset":"m_debt_tell"}'::jsonb, now() + interval '365 days', now() - interval '10 hours'),
  ('ask_m_moveback', 'uSjoSmjC', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Rent is insane. Move back in with my parents for a year to save?', 'I''m 27 and my mom already cleared out my old room.', 'other', '{"askingPreset":"m_moveback"}'::jsonb, now() + interval '365 days', now() - interval '26 hours'),
  ('ask_m_gift_limit', 'xHEzMoJr', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Money''s tight this year. Tell my family I''m doing a $25 gift limit?', NULL, 'other', '{"askingPreset":"m_gift_limit"}'::jsonb, now() + interval '365 days', now() - interval '28 hours'),
  ('ask_m_recession', 'LFADBToT', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Everyone keeps saying recession. Keep putting money in my 401k or build up cash?', NULL, 'other', '{"askingPreset":"m_recession"}'::jsonb, now() + interval '365 days', now() - interval '16 hours'),
  ('ask_m_baby_afford', 'AQ4w5N2i', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Not sure we can afford a baby right now. Wait a couple of years or go for it?', 'Daycare near us is $1,900 a month.', 'other', '{"askingPreset":"m_baby_afford"}'::jsonb, now() + interval '365 days', now() - interval '6 hours'),
  ('ask_w_layoffs', '3qskoAsR', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Layoffs keep happening at my company. Start job hunting now or wait it out?', 'They cut 10% in March and there are rumors again.', 'other', '{"askingPreset":"w_layoffs"}'::jsonb, now() + interval '365 days', now() - interval '40 hours'),
  ('ask_w_ai', 'BuCFsTfA', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Scared AI is going to replace my job. Learn the AI tools or start switching careers?', NULL, 'other', '{"askingPreset":"w_ai"}'::jsonb, now() + interval '365 days', now() - interval '3 hours'),
  ('ask_w_partner_laidoff', 'exJkypA5', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'My partner just got laid off. Cancel our trip or keep it so we have something to look forward to?', NULL, 'other', '{"askingPreset":"w_partner_laidoff"}'::jsonb, now() + interval '365 days', now() - interval '20 hours'),
  ('ask_w_lower_offer', 'cKbj5Lsz', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Out of work four months. Take an offer that pays $15k less than my last job?', NULL, 'other', '{"askingPreset":"w_lower_offer"}'::jsonb, now() + interval '365 days', now() - interval '37 hours'),
  ('ask_w_raise_cuts', 'PUxAXTrx', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Ask for a raise even though my company just did layoffs?', 'Rent went up $250 and I''m doing two people''s work now.', 'other', '{"askingPreset":"w_raise_cuts"}'::jsonb, now() + interval '365 days', now() - interval '33 hours'),
  ('ask_f_politics', '2GawuyKu', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'My uncle always starts on politics at Thanksgiving. Push back or change the subject?', NULL, 'other', '{"askingPreset":"f_politics"}'::jsonb, now() + interval '365 days', now() - interval '17 hours'),
  ('ask_f_dad_rep', 'g9qAC5DX', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'My dad''s a Republican and I''m a Democrat. Invite him over for the holidays or skip the stress?', 'Last time it ended with my mom crying in the kitchen.', 'other', '{"askingPreset":"f_dad_rep"}'::jsonb, now() + interval '365 days', now() - interval '7 hours'),
  ('ask_f_parents_dem', 'phGF4tpU', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'I''m a Republican and my parents are Democrats. Bring up politics with them or keep it off limits?', NULL, 'other', '{"askingPreset":"f_parents_dem"}'::jsonb, now() + interval '365 days', now() - interval '14 hours'),
  ('ask_f_inlaws_vote', 'TrRRqngW', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'My in-laws vote the opposite way and it comes up at every dinner. Say something or let my partner handle it?', NULL, 'other', '{"askingPreset":"f_inlaws_vote"}'::jsonb, now() + interval '365 days', now() - interval '31 hours'),
  ('ask_f_mom_posts', 'nnq5oxWL', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'My mom keeps posting political stuff that makes me so mad. Mute her or actually talk to her about it?', NULL, 'other', '{"askingPreset":"f_mom_posts"}'::jsonb, now() + interval '365 days', now() - interval '28 hours'),
  ('ask_f_brother_reach', 'BH5seiTb', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Haven''t talked to my brother since we fought about politics. Reach out first or wait for him?', 'I love him. I just don''t know how to start.', 'other', '{"askingPreset":"f_brother_reach"}'::jsonb, now() + interval '365 days', now() - interval '7 hours'),
  ('ask_f_wedding_wait', 'eqKF9V8b', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Everything costs so much. Push the wedding back a year to save, or do a small one now?', NULL, 'other', '{"askingPreset":"f_wedding_wait"}'::jsonb, now() + interval '365 days', now() - interval '20 hours'),
  ('ask_l_cheaper', 'YhnF92xA', (SELECT id FROM "user" WHERE handle = 'peoplelikeyou'), 'Everything costs too much here. Move somewhere cheaper or stay near my friends?', 'Same job, remote, and I''d save about $900 a month.', 'other', '{"askingPreset":"l_cheaper"}'::jsonb, now() + interval '365 days', now() - interval '16 hours')
